from django.contrib import admin
from django.utils.html import format_html
from .models import Author, Category, Book


@admin.register(Author)
class AuthorAdmin(admin.ModelAdmin):
    list_display = ["full_name", "nationality", "books_count", "is_deleted"]
    list_filter = ["nationality", "is_deleted"]
    search_fields = ["full_name", "bio"]
    prepopulated_fields = {"slug": ("full_name",)}

    def books_count(self, obj):
        return obj.books.count()
    books_count.short_description = "تعداد کتاب‌ها"


@admin.register(Category)
class CategoryAdmin(admin.ModelAdmin):
    list_display = ["name", "parent", "order", "books_count"]
    list_filter = ["parent"]
    search_fields = ["name"]
    prepopulated_fields = {"slug": ("name",)}

    def books_count(self, obj):
        return obj.books.count()


@admin.register(Book)
class BookAdmin(admin.ModelAdmin):
    list_display = [
        "title", "author", "price", "final_price_display",
        "stock", "is_published", "is_featured", "created_at",
    ]
    list_filter = ["is_published", "is_featured", "language", "is_deleted", "author"]
    search_fields = ["title", "isbn", "description", "author__full_name"]
    prepopulated_fields = {"slug": ("title",)}
    date_hierarchy = "published_at"
    filter_horizontal = ["categories"]
    readonly_fields = ["views_count", "loans_count", "created_at", "updated_at"]

    fieldsets = (
        ("اطلاعات اصلی", {
            "fields": ("title", "slug", "subtitle", "description", "language"),
        }),
        ("روابط", {
            "fields": ("author", "categories", "owner"),
        }),
        ("شناسه و فایل", {
            "fields": ("isbn", "cover", "document"),
        }),
        ("قیمت", {
            "fields": ("price", "discount_price"),
        }),
        ("مشخصات", {
            "fields": ("published_at", "pages", "publisher"),
        }),
        ("موجودی و وضعیت", {
            "fields": ("stock", "total_copies", "is_published", "is_featured"),
        }),
        ("آمار", {
            "fields": ("views_count", "loans_count", "created_at", "updated_at"),
            "classes": ("collapse",),
        }),
    )

    def final_price_display(self, obj):
        if obj.has_discount:
            return format_html(
                '<span style="color: red;">{}</span> <s>{}</s>',
                obj.final_price, obj.price,
            )
        return obj.price
    final_price_display.short_description = "قیمت نهایی"
